import{_ as o,c as r,o as i,aM as t}from"./chunks/framework.kKeYZnSg.js";const a="/fe-handbook/assets/20200705231430822.58RrLOwI.png",n="/fe-handbook/assets/2020070523132367.C8Uwv58L.png",l="/fe-handbook/assets/%E5%AE%B9%E5%99%A8%E7%94%9F%E6%80%81.BFAWBGat.png",k=JSON.parse('{"title":"Docker","description":"","frontmatter":{},"headers":[],"relativePath":"advance/devops/docker/index.md","filePath":"advance/devops/docker/index.md","lastUpdated":1779720401000}'),s={name:"advance/devops/docker/index.md"};function p(c,e,d,u,h,m){return i(),r("div",null,e[0]||(e[0]=[t('<h1 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h1><p><a href="https://www.docker.com/" target="_blank" rel="nofollow noopener noreferrer">Docker: Accelerated Container Application Development</a></p><p><em>&quot;Debug your app, not your environment.&quot;</em></p><p><em>&quot;Develop faster. Run anywhere.&quot;</em></p><ul><li>官方文档：<a href="https://docs.docker.com/" target="_blank" rel="nofollow noopener noreferrer">https://docs.docker.com/</a></li><li>官方桌面客户端：<a href="https://www.docker.com/products/docker-desktop/" target="_blank" rel="nofollow noopener noreferrer">https://www.docker.com/products/docker-desktop/</a></li><li>官方镜像仓库：<a href="https://hub.docker.com/" target="_blank" rel="nofollow noopener noreferrer">https://hub.docker.com/</a></li><li><a href="http://dockerhub.com/" target="_blank" rel="nofollow noopener noreferrer">http://dockerhub.com/</a> 301 Moved Permanently</li><li><a href="https://docs.docker.com/get-started/docker_cheatsheet.pdf" target="_blank" rel="nofollow noopener noreferrer">docker cheatsheet</a></li><li>学习仓库：<a href="https://github.com/zlx01/ok-docker" target="_blank" rel="nofollow noopener noreferrer">https://github.com/zlx01/ok-docker</a></li></ul><h2 id="what-is-docker" tabindex="-1"><strong>What is Docker?</strong> <a class="header-anchor" href="#what-is-docker" aria-label="Permalink to &quot;**What is Docker?**&quot;">​</a></h2><p>先看官方文档怎么说。</p><blockquote><p>Docker is an open platform for developing, shipping, and running applications.</p></blockquote><blockquote><p><strong>Accelerate how you build, share, and run applications</strong></p></blockquote><blockquote><p>Docker helps developers build, share, run, and verify applications anywhere — without tedious environment configuration or management.</p></blockquote><ul><li>应用容器引擎</li></ul><h3 id="build" tabindex="-1"><strong>Build</strong> <a class="header-anchor" href="#build" aria-label="Permalink to &quot;**Build**&quot;">​</a></h3><ul><li><p><strong>Spin up new environments quickly</strong></p><p>Develop your own unique applications with Docker images and create multiple containers using Docker Compose.</p></li><li><p><strong>Integrate with your existing tools</strong></p><p>Docker works with all development tools such as VS Code, CircleCI, and GitHub.</p></li><li><p><strong>Containerize applications for consistency</strong></p><p>Run in any environment consistently from on-premises Kubernetes to AWS ECS, Azure ACI, Google GKE, and more.</p></li></ul><h3 id="share" tabindex="-1"><strong>Share</strong> <a class="header-anchor" href="#share" aria-label="Permalink to &quot;**Share**&quot;">​</a></h3><ul><li><p><strong>Build with verified, trusted content</strong></p><p>Visit Docker Hub to browse Docker Trusted Content from our verified publishers or Docker Official Images.</p></li><li><p><strong>Collaborate with your team</strong></p><p>Pull and publish images from Hub for easy sharing between team members, organizations, or the broader community.</p></li><li><p><strong>Secure your workspaces</strong></p><p>Ensure best practices with image access management, registry access management, and private repositories.</p></li></ul><h3 id="run" tabindex="-1"><strong>Run</strong> <a class="header-anchor" href="#run" aria-label="Permalink to &quot;**Run**&quot;">​</a></h3><ul><li><p><strong>Cross-Platform Reliability</strong></p><p>Ensure your applications run consistently across various environments, fostering reliability and eliminating compatibility issues.</p></li><li><p><strong>Versatile Development Experience</strong></p><p>Work in isolated containers with support for multiple languages, reducing conflicts between dependencies and providing a flexible development experience.</p></li><li><p><strong>Effortless Deployment</strong></p><p>Simplify your development process with streamlined deployment using a single command. Save time and effort while managing your applications seamlessly.</p></li></ul><h3 id="verify" tabindex="-1"><strong>Verify</strong> <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;**Verify**&quot;">​</a></h3><ul><li><p><strong>Stay vigilant with unified analysis</strong></p><p>Address security issues before they hit production through a complete view of the software supply chain.</p></li><li><p><strong>Do more with streamlined workflows</strong></p><p>Build more efficiently with recommended remediation, resulting in simplified development processes.</p></li><li><p><strong>Act quickly on prioritized actions</strong></p><p>Follow key insights aligned with policy guardrails to stay ahead of security issues before they occur.</p></li></ul><h2 id="虚拟化技术" tabindex="-1">虚拟化技术 <a class="header-anchor" href="#虚拟化技术" aria-label="Permalink to &quot;虚拟化技术&quot;">​</a></h2><ul><li>将计算机的各种硬件资源，例如CPU、内存、磁盘以及网络等，看做资源池，系统管理员可以对其进行重新分配，而不用考虑底层物理硬件</li><li>虚拟化技术解决的问题：1.高性能计算机硬件的产能过剩；2.把老旧的计算机硬件重新组合，作为一个整体的资源来用，化零为整。</li><li>Linux平台的虚拟化产品：KVM，Xen，VMWare，VirtualBox</li><li>Windows平台的虚拟化产品：Hyper V，VMWare，VirtualBox</li><li>虚拟化系统可以在宿主机上虚拟化出一套完整的硬件基础设施，配以操作系统，相当于虚拟出一台计算机</li><li>虚拟机对底层系统来说，就是一个文件。</li><li>虚拟机之间是相互隔离的。</li><li>虚拟化技术的缺点：资源占用多，一个虚拟机实例需要完整的操作系统及其附属应用，实际可能只需要部分功能和应用；冗余步骤多，启动慢</li></ul><h2 id="容器技术" tabindex="-1">容器技术 <a class="header-anchor" href="#容器技术" aria-label="Permalink to &quot;容器技术&quot;">​</a></h2><ul><li>容器，是一种轻量级的操作系统级的虚拟化，可以让用户在一个资源隔离的进程中运行应用及其依赖项。运行应用程序所必须的组件都讲打包成一个镜像并可以复用。</li></ul><h2 id="docker与虚拟机的比较" tabindex="-1">docker与虚拟机的比较 <a class="header-anchor" href="#docker与虚拟机的比较" aria-label="Permalink to &quot;docker与虚拟机的比较&quot;">​</a></h2><p><img src="'+a+'" alt="20200705231430822.png"></p><p><img src="'+n+'" alt="2020070523132367.png"></p><h2 id="为什么需要docker" tabindex="-1">为什么需要docker？ <a class="header-anchor" href="#为什么需要docker" aria-label="Permalink to &quot;为什么需要docker？&quot;">​</a></h2><ul><li>解决的问题：开发环境和生产环境的一致性（依赖，版本，配置，网络。。。）</li><li>跨平台容易，方便部署，扩展，迁移。</li><li>一次构建、随处运行（<strong>Build once，Run everywhere</strong>）</li><li>举例：一般通过LAMP搭建网站时，往往需要很多配置环境的操作，当迁移系统到其他云平台时，需要重新部署和调试，而有了容器技术来打包应用，迁移系统就变得在新的云平台上启动容器那么简单了</li></ul><h2 id="docker在devops-开发-运维-中的优势" tabindex="-1">docker在DevOps（开发/运维）中的优势？ <a class="header-anchor" href="#docker在devops-开发-运维-中的优势" aria-label="Permalink to &quot;docker在DevOps（开发/运维）中的优势？&quot;">​</a></h2><ul><li>敏捷：更快速的交付和部署</li><li>提高生产力：容器可以看做一个微服务，容器之间相互独立，可以独立升级，避免跨服务的依赖和冲突</li><li>节省资源：不需要额外的虚拟化管理程序支持</li><li>安全：容器之间的进程是相互隔离的（使用沙箱技术）</li></ul><h2 id="容器生态" tabindex="-1">容器生态 <a class="header-anchor" href="#容器生态" aria-label="Permalink to &quot;容器生态&quot;">​</a></h2><p><img src="'+l+'" alt="容器生态.png"></p><h3 id="oci-open-container-initiative-开放容器标准" tabindex="-1">OCI （Open Container Initiative/开放容器标准） <a class="header-anchor" href="#oci-open-container-initiative-开放容器标准" aria-label="Permalink to &quot;OCI （Open Container Initiative/开放容器标准）&quot;">​</a></h3><ul><li>OCI Image Spec：容器镜像标准</li><li>OCI Runtime Spec：容器运行标准</li></ul>',34)]))}const f=o(s,[["render",p]]);export{k as __pageData,f as default};
